DROP TABLE IF EXISTS `solicitudes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `solicitudes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `direccion_id` int DEFAULT NULL,
  `area_id` int DEFAULT NULL,
  `cargo_id` int DEFAULT NULL,
  `jefe_asignado_id` int DEFAULT NULL,
  `maxima_autoridad_id` int DEFAULT NULL,
  `codigo_solicitud` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombres_completos` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cedula` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `correo_institucional` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `telefono_ext` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dependencia` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `area_unidad` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cargo` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fecha_solicitud` date NOT NULL,
  `tipo_usuario` enum('funcionario_inamhi','externo') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'funcionario_inamhi',
  `nombre_usuario_externo` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `direccion_ip` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tiempo_vigencia_acceso` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `justificacion_necesidad_institucional` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `estado` enum('borrador','pendiente_firma_solicitante','pendiente_jefe_inmediato','rechazada_jefe_inmediato','pendiente_maxima_autoridad','rechazada_maxima_autoridad','pendiente_tics','rechazada_tics','pendiente_ejecucion_tics','finalizada','anulada') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pendiente_firma_solicitante',
  `etapa_actual` enum('registro_publico','firma_solicitante','jefe_inmediato','maxima_autoridad','tics','ejecucion_tics','finalizado') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'firma_solicitante',
  `bloqueada` tinyint(1) NOT NULL DEFAULT '0',
  `observacion_general` text COLLATE utf8mb4_unicode_ci,
  `documento_actual_id` int DEFAULT NULL,
  `requiere_firma` tinyint DEFAULT '1',
  `firma_actual_validada` tinyint DEFAULT '0',
  `motivo_rechazo` text COLLATE utf8mb4_unicode_ci,
  `fecha_rechazo` datetime DEFAULT NULL,
  `rechazado_por_usuario_id` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo_solicitud` (`codigo_solicitud`),
  KEY `idx_solicitudes_codigo` (`codigo_solicitud`),
  KEY `idx_solicitudes_cedula` (`cedula`),
  KEY `idx_solicitudes_correo` (`correo_institucional`),
  KEY `idx_solicitudes_estado` (`estado`),
  KEY `idx_solicitudes_etapa` (`etapa_actual`),
  KEY `idx_solicitudes_direccion_id` (`direccion_id`),
  KEY `idx_solicitudes_area_id` (`area_id`),
  KEY `idx_solicitudes_cargo_id` (`cargo_id`),
  KEY `idx_solicitudes_jefe_asignado_id` (`jefe_asignado_id`),
  KEY `idx_solicitudes_estado_etapa` (`estado`,`etapa_actual`),
  CONSTRAINT `fk_solicitudes_area` FOREIGN KEY (`area_id`) REFERENCES `areas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_solicitudes_cargo` FOREIGN KEY (`cargo_id`) REFERENCES `cargos` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_solicitudes_direccion` FOREIGN KEY (`direccion_id`) REFERENCES `direcciones` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
